#!/bin/bash
# Self-contained fix: dashboard feed status + freshness, ThreatFox wiring tests,
# and removal of the dead malicious-domains-cdb.txt. No network, no patch context.
set -euo pipefail
REPO="${1:-$HOME/OpenIOCCollector}"
cd "$REPO"
echo "== writing files into $REPO =="
:
base64 -d > generate_dashboard.py <<'B64'

B64
echo "   wrote generate_dashboard.py"
mkdir -p tests
base64 -d > tests/test_dashboard.py <<'B64'

B64
echo "   wrote tests/test_dashboard.py"
mkdir -p tests
base64 -d > tests/test_threatfox_wiring.py <<'B64'

B64
echo "   wrote tests/test_threatfox_wiring.py"
git rm --quiet --ignore-unmatch malicious-domains-cdb.txt || true
echo "== running tests =="
python3 -m unittest discover -s tests
echo "== regenerating the dashboard =="
python3 generate_dashboard.py
echo "== diff stat =="
git status --short
echo
echo "Check the rendered page, then: git add -A && git commit -m \"Dashboard: report feed failures honestly; freshness banner; ThreatFox wiring tests\" && git push"
